      (* [comment removed for export] *)
      Theorem as_file :
        (length path <= 4095)%nat -> path <> [] -> path_has_slash path = false -> path_is_dirref path = false ->
        realizes bsegs (mkCfg msF0 mo0) (t_alt2 (t_die (msg_cannot_open path) (m_fs mo0)) (t_opened data (m_fs mo0))).
      Proof using HCEIL H HH DL TR LIVE TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can Hva PRE RDR a0s path Hargv p0 pp Hp0 Hpp data Hdata.
        intros Hlen Hne Hsl Hnd. pose proof SPlo as Hlo. pose proof SPhi as Hhi. pose proof Elo.
        pose proof (am_fds _ _ _ _ _ _ _ _ _ _ _ PRE) as FDS0.
        apply (aseg_A H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE a0s path Hargv p0 pp Hp0 Hpp).
        intros R M msF mo HV HA SB HR HK FM FA.
        pose proof (amst_at_open M FM FA) as ST. pose proof (arh_at_open M FM) as RH.
        destruct (aopenat_regs sp0 regs0 tid can p0 pp R HR) as (H17 & H10 & H11 & Hfl).
        pose proof (apath_at_A H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE path p0 pp Hpp M R FM HR Hlen) as PA.
        destruct (mo_sb _ _ SB) as [EFS EFDS].
        assert (RDm : m_channel_reader mo = true) by (rewrite (same_but_materialized_reader _ _ SB); exact RDR).
        assert (Hfree : fd_lookup (m_fds mo) (alloc_fd (m_fds mo)) = None) by (rewrite EFDS, FDS0; reflexivity).
        unfold t_opened. rewrite <- EFS.
        eapply (drv_openat_file H DL s0 msF R (Z_to_bv 64 0x11281c) M mo ECALLW AECALL2 is_ecall_ECALLW HV HA H17 H10 Hfl Hfree path data);
          [ exact PA | exact Hne | exact Hsl | exact Hnd | rewrite EFS; exact Hdata | |].
        - (* openat failed: the cannot-open tail *)
          intros e msF' mo' He HV' HA' SB'. rewrite AgentLib.v_addi_lit in HV' by lia. change (0x11281c + 4)%Z with 0x112820%Z in HV'.
          eapply (aseg_F H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE p0 pp e R M msF' mo' _ HV' HA' (openat_errnos_range e He) (scF_openat e He) HR HK).
          intros R' M' msF2 mo2 HV2 HA2 SB2 Q2 Q4 Q8 Q18 FM2.
          rewrite <- (same_but_materialized_fs _ _ SB'), <- (same_but_materialized_fs _ _ SB2).
          eapply (TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can a0s path pp s0 msF2 mo2 R' M' Hva PRE Hargv (proj1 Hpp) (proj2 Hpp) HV2 HA2 Q2 Q4 Q18).
          + pose proof (frame_mod_munch _ _ _ FM2) as MU2. unfold aregF_w, ivls in MU2. cbn [map fst snd] in MU2. rewrite !u_small in MU2 by lia.
            eapply (mstatics_munch H HH sp0 tid can mem0 Hvsp HCE M M' _ [] ST MU2 (aframe_mod_wmono _ _ _ FM2)).
            * constructor; [left; cbn [fst snd]; lia | constructor; [right; left; reflexivity | constructor]].
            * eapply amem_inv_frame; [exact (mst_inv H sp0 tid can mem0 _ ST) | exact FM2 |].
              unfold aregF_w. constructor; [| constructor; [|constructor]]; cbn [fst snd]; rewrite u_small by lia; lia.
            * apply (astk_grows M M'); [exact (mst_stk_spm H sp0 tid can mem0 Hvsp _ ST) | lia | lia | exact (proj2 FM2)].
            * eapply ACONST_frame; [exact (mst_ac H sp0 tid can mem0 _ ST) | exact MU2 | exact (aframe_mod_wmono _ _ _ FM2) |].
              constructor; [apply aconst_ok_hi; cbn [fst]; unfold AHI_LO; lia | constructor; [exact aconst_ok_errno | constructor]].
          + rewrite (same_but_materialized_fds _ _ SB2), (same_but_materialized_fds _ _ SB'), EFDS, FDS0. reflexivity.
          + rewrite (same_but_materialized_reader _ _ SB2), (same_but_materialized_reader _ _ SB'). exact RDm.
        - (* opened as fd 3: the first allocation, then the read loop *)
          intros msF' mo' HV' HA' SB'. rewrite AgentLib.v_addi_lit in HV' by lia. change (0x11281c + 4)%Z with 0x112820%Z in HV'.
          replace (alloc_fd (m_fds mo)) with (Z_to_bv 64 3) in HV', SB' by (rewrite EFDS, FDS0; reflexivity).
          eapply (aseg_C H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE p0 pp R M msF' mo' _ HV' HA' HR HK).
          intros R' msF2 mo2 HV2 HA2 SB2 Q1 Q2 Q4 Q8 Q10 Q18 Q20 Q21.
          change (Z_to_bv 64 0x74544) with (Z_to_bv 64 AMALLOC_STUB) in HV2.
          eapply (first_alloc R' M msF2 mo2 _ HV2 HA2 Q1 Q2 Q4 Q8 Q10 Q18 Q20 Q21 ST RH (am_al _ _ _ _ _ _ _ _ _ _ _ PRE)).
          intros regs3 mem3 msF3 mo3 A p s HV3 HA3 RC RH3 CB3 AD3 ST3 HAL3 FS3 FDS3 RD3.
          (* the reader of the loop's start model: first_alloc's equation, then SB2 and SB' back to RDm *)
          assert (RDR3 : m_channel_reader mo3 = true).
          { rewrite RD3, (same_but_materialized_reader _ _ SB2), (same_but_materialized_reader _ _ SB'). exact RDm. }
          eapply (loop_sound H HH DL sp0 pp tid can path data (m_fs mo) mem0 Hvsp HCE ltac:(rewrite EFS; exact Hdata) Htid TRC LIVE
                    (length data) 0 65536 A s p regs3 mem3 msF3 mo3).
          + lia.
          + exact HV3.
          + exact HA3.
          + eapply (ARInv0 data (m_fs mo) mo2); try eassumption.
            * rewrite (same_but_materialized_fs _ _ SB2), (same_but_materialized_fs _ _ SB'). reflexivity.
            * rewrite (same_but_materialized_fds _ _ SB2), (same_but_materialized_fds _ _ SB'), with_fds_fds, EFDS. reflexivity.
          + intros cap' A' s' p' regs4 mem4 msF4 mo4 HV4 HA4 CI RD4.
            eapply (close_step H DL sp0 pp tid can data (m_fs mo) mem0); [exact HV4 | exact HA4 | exact CI |].
            intros regs5 msF5 mo5 HV5 HA5 XI RD5. rewrite EFS.
            eapply x_header; [exact HV5 | exact HA5 | rewrite <- EFS; exact XI | rewrite RD5, RD4; exact RDR3].
          + intros Hbig A' s' p' regs4 mem4 msF4 mo4 HV4 HA4 RF RD4.
            unfold t_body. replace (MAX_INPUT <=? Z.of_nat (length data))%Z with true by (symmetry; apply Z.leb_le; lia).
            eapply (refuse_exit H DL sp0 tid can Hvsp HCE Htid mem0 pp); [exact HV4 | exact HA4 | exact RF | rewrite RD4; exact RDR3].
      Qed.
    End File.

    (* [comment removed for export] *)
    Lemma open_fail : forall e R M msF' mo',
      In e openat_errnos \/ e = ENAMETOOLONG \/ e = ENOENT ->
      regs_ok E0 srA R -> know_ok RSEGS E0 M knA -> mstatics H sp0 tid can mem0 M ->
      as_VIS H s0 msF' = mkst (regupd R 10 (errno_ret e)) (Z_to_bv 64 0x112820) M rom -> as_AKREL H s0 (mkCfg msF' mo') ->
      m_fds mo' = m_fds mo0 ->
      m_channel_reader mo' = true ->
      realizes bsegs (mkCfg msF' mo') (t_die (msg_cannot_open path) (m_fs mo')).
    Proof using HCEIL H HH DL TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can Hva PRE RDR a0s path Hargv p0 pp Hpp.
      intros e R M msF' mo' He HR HK ST HV' HA' EFDS ERDR. pose proof SPlo as Hlo. pose proof SPhi as Hhi. pose proof Elo. pose proof aceil_loT as HCL. acb.
      pose proof (am_fds _ _ _ _ _ _ _ _ _ _ _ PRE) as FDS0.
      assert (HeR : 1 <= e <= 4095 /\ scF e).
      { destruct He as [He|[->| ->]]; [split; [apply openat_errnos_range | apply scF_openat]; exact He
          | split; [unfold ENAMETOOLONG; lia | exact scF_ENAMETOOLONG] | split; [unfold ENOENT; lia | exact scF_ENOENT]]. }
      destruct HeR as [HeR HSC].
      eapply (aseg_F H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE p0 pp e R M msF' mo' _ HV' HA' HeR HSC HR HK).
      intros R' M' msF2 mo2 HV2 HA2 SB2 Q2 Q4 Q8 Q18 FM2.
      rewrite <- (same_but_materialized_fs _ _ SB2).
      eapply (TOP sp0 argv s0 msF0 mo0 regs0 mem0 B tid can a0s path pp s0 msF2 mo2 R' M' Hva PRE Hargv (proj1 Hpp) (proj2 Hpp) HV2 HA2 Q2 Q4 Q18).
      - pose proof (frame_mod_munch _ _ _ FM2) as MU2. unfold aregF_w, ivls in MU2. cbn [map fst snd] in MU2. rewrite !u_small in MU2 by lia.
        eapply (mstatics_munch H HH sp0 tid can mem0 Hvsp HCE M M' _ [] ST MU2 (aframe_mod_wmono _ _ _ FM2)).
        + constructor; [left; cbn [fst snd]; lia | constructor; [right; left; reflexivity | constructor]].
        + eapply amem_inv_frame; [exact (mst_inv H sp0 tid can mem0 _ ST) | exact FM2 |].
          unfold aregF_w. constructor; [| constructor; [|constructor]]; cbn [fst snd]; rewrite u_small by lia; lia.
        + apply (astk_grows M M'); [exact (mst_stk_spm H sp0 tid can mem0 Hvsp _ ST) | lia | lia | exact (proj2 FM2)].
        + eapply ACONST_frame; [exact (mst_ac H sp0 tid can mem0 _ ST) | exact MU2 | exact (aframe_mod_wmono _ _ _ FM2) |].
          constructor; [apply aconst_ok_hi; cbn [fst]; unfold AHI_LO; lia | constructor; [exact aconst_ok_errno | constructor]].
      - rewrite (same_but_materialized_fds _ _ SB2), EFDS, FDS0. reflexivity.
      - rewrite (same_but_materialized_reader _ _ SB2). exact ERDR.
    Qed.

    (* [comment removed for export] *)
    Theorem as_open_fail_toolong :
      (4096 <= length path)%nat ->
      realizes bsegs (mkCfg msF0 mo0) (t_die (msg_cannot_open path) (m_fs mo0)).
    Proof.
      (* LPS 75d69e00: [drv_openat_toolong] now also takes the TASK_SIZE bound on the
         4096-byte read (the model's [cstr_access_len_aux] passes [access_okb] per byte), so
         the recorded proof no longer fits; restated by hand, same text as As/AsMainTop.v's
         as_open_fail_toolong (bsegs, call site 0x11281c), with the recorded proof's own
         lemmas (rdn_agree/above_A, rdn_firstn, firstn_app, firstn_skipn).  The bound is
         astr_at's `pp + length path + 10 <= 0x800000000000` = TASK_SIZE. *)
      intros Hlong. pose proof SPlo as Hlo. pose proof SPhi as Hhi.
      apply (aseg_A H DL sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE a0s path Hargv p0 pp Hp0 Hpp).
      intros R M msF mo HV HA SB HR HK FM FA.
      pose proof (amst_at_open M FM FA) as ST. destruct (mo_sb _ _ SB) as [EFS EFDS].
      destruct (aopenat_regs sp0 regs0 tid can p0 pp R HR) as (H17 & H10 & H11 & Hfl).
      destruct Hpp as [_ (S1a & S1b & S1c & S1d & S1e)].
      assert (HrdM : rdn bsegs M (Z_to_bv 64 pp) (length path + 1) = Some (path ++ [Z_to_bv 8 0])).
      { rewrite <- S1d. apply rdn_agree. intros j Hj.
        apply (above_A H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE M FM). unorm. lia. }
      assert (Hrd : rdn bsegs M (getr R 11) 4096 = Some (firstn 4096 path)).
      { rewrite H11, (rdn_firstn _ _ _ _ _ 4096 HrdM) by lia.
        rewrite firstn_app.
        replace (4096 - length path)%nat with 0%nat by lia.
        rewrite firstn_O, app_nil_r. reflexivity. }
      assert (Hnz : ~ In (Z_to_bv 8 0) (firstn 4096 path)).
      { intro Hin. apply S1c. rewrite <- (firstn_skipn 4096 path). apply in_or_app. left. exact Hin. }
      assert (Hts : (bv_unsigned (getr R 11) + 4096 <= TASK_SIZE)%Z).
      { rewrite H11. unfold TASK_SIZE. unorm. lia. }
      eapply (drv_openat_toolong H DL s0 msF R (Z_to_bv 64 0x11281c) M mo ECALLW AECALL2 is_ecall_ECALLW HV HA H17 H10 Hfl (firstn 4096 path));
        [exact Hrd | exact Hnz | exact Hts |].
      intros msF' mo' HV' HA' SB'. rewrite AgentLib.v_addi_lit in HV' by lia. change (0x11281c + 4)%Z with 0x112820%Z in HV'.
      rewrite <- EFS, <- (same_but_materialized_fs _ _ SB').
      apply (open_fail ENAMETOOLONG R M msF' mo' ltac:(right; left; reflexivity) HR HK ST HV' HA').
      - rewrite (same_but_materialized_fds _ _ SB'). exact EFDS.
      - rewrite (same_but_materialized_reader _ _ SB'), (same_but_materialized_reader _ _ SB). exact RDR.
    Qed.

