      pose proof (apath_at_A H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can PRE path p0 pp Hpp M R FM HR ltac:(rewrite Hnil; cbn; lia)) as PA.
      eapply (drv_openat_empty H DL s0 msF R (Z_to_bv 64 0x11281c) M mo ECALLW AECALL2 is_ecall_ECALLW HV HA H17 H10 Hfl).
      - rewrite Hnil in PA. exact PA.
