Lemma list_byte_eqb_eq : forall p q, list_byte_eqb p q = true <-> p = q.
Proof.
  induction p as [|a p IH]; intros [|b q]; cbn; try (split; [discriminate|congruence]).
  - split; reflexivity.
  - rewrite andb_true_iff, IH. unfold bv_eqb. rewrite Z.eqb_eq. split.
    + intros [Hab ->]. f_equal. apply bv_eq. exact Hab.
    + intros E. injection E as -> ->. split; reflexivity.
Qed.

Section Main.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis DL : asan_driver_laws H.
  Hypothesis TR : as_target_run_stmt H.
  Hypothesis LIVE : ADRV_LIVE <= as_LIVE_MAX H /\ ADRV_CNT <= as_LIVE_CNT_MAX H.
  Hypothesis TUS : atail_usage_stmt H.
  Hypothesis TOP : atail_open_stmt H.
  Hypothesis TRD : atail_rderr_stmt H.
Scheme kc__14 := Elimination for Corelib.Init.Datatypes.list Sort Prop.
Scheme kc__15 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__16 := Elimination for Corelib.Init.Datatypes.option Sort Prop.

  Theorem as_main_realizes : as_main_realizes_stmt H.
  Proof using HCEIL H HH DL TR LIVE TUS TOP TRD.
    intros sp0 argv s0 msF mo regs mem B tid can Hva Hvfs PRE RDR.
    destruct argv as [|a0s [|path [|x l]]].
    - exact (as_usage H HH DL TUS sp0 [] s0 msF mo regs mem B tid can Hva PRE RDR ltac:(cbn; lia)).
    - exact (as_usage H HH DL TUS sp0 [a0s] s0 msF mo regs mem B tid can Hva PRE RDR ltac:(cbn; lia)).
    - cbn [spec].
      pose proof Hva as (_ & _ & _ & _ & Htl). cbn [tl] in Htl. inversion Htl as [|x l [Hsl Hdd] _]; subst.
      destruct (am_args _ _ _ _ _ _ _ _ _ _ _ PRE 0%nat a0s ltac:(lia) eq_refl) as [p0 Hp0].
      destruct (am_args _ _ _ _ _ _ _ _ _ _ _ PRE 1%nat path ltac:(lia) eq_refl) as [pp Hpp].
      cbn [Z.of_nat Z.mul Pos.of_succ_nat Pos.mul Z.add] in Hp0, Hpp.
      replace (bv_unsigned sp0 + 8 + 0) with (bv_unsigned sp0 + 8) in Hp0 by lia.
      replace (bv_unsigned sp0 + 8 + 8) with (bv_unsigned sp0 + 16) in Hpp by lia.
      destruct (Nat.leb_spec0 4096 (length path)) as [Hlong|Hshort].
      + exact (as_open_fail_toolong H HH DL TOP sp0 [a0s; path] s0 msF mo regs mem B tid can Hva PRE RDR a0s path eq_refl p0 pp Hp0 Hpp Hlong).
      + destruct (list_byte_eqb path []) eqn:Hemp.
        * apply list_byte_eqb_eq in Hemp.
          exact (as_open_fail_empty H HH DL TOP sp0 [a0s; path] s0 msF mo regs mem B tid can Hva PRE RDR a0s path eq_refl p0 pp Hp0 Hpp Hemp).
        * assert (Hne : path <> []) by (intros E; apply list_byte_eqb_eq in E; rewrite E in Hemp; discriminate).
          destruct (list_byte_eqb path dot_path) eqn:Hdot.
          -- apply list_byte_eqb_eq in Hdot.
             exact (as_dir H HH DL LIVE TOP TRD sp0 [a0s; path] s0 msF mo regs mem B tid can Hva PRE RDR a0s path eq_refl p0 pp Hp0 Hpp Hdot).
          -- assert (Hnd : path <> dot_path) by (intros E; apply list_byte_eqb_eq in E; rewrite E in Hdot; discriminate).
             assert (Hdr : path_is_dirref path = false).
             { unfold path_is_dirref. rewrite (path_eqb_neq _ _ Hnd), Hdd. reflexivity. }
             destruct (fs_lookup (m_fs mo) path) as [data|] eqn:Hlk.
             ++ exact (as_file H HH DL TR LIVE TOP sp0 [a0s; path] s0 msF mo regs mem B tid can Hva PRE RDR a0s path eq_refl p0 pp Hp0 Hpp data Hlk
                        ltac:(lia) Hne Hsl Hdr).
             ++ exact (as_open_fail_absent H HH DL TOP sp0 [a0s; path] s0 msF mo regs mem B tid can Hva PRE RDR a0s path eq_refl p0 pp Hp0 Hpp
                        ltac:(lia) Hne Hsl Hdr Hlk).
    - exact (as_usage H HH DL TUS sp0 (a0s :: path :: x :: l) s0 msF mo regs mem B tid can Hva PRE RDR ltac:(cbn; lia)).
  Qed.
End Main.
